       "id": "m04-l02-p02-b01",
       "type": "code",
       "language": "csharp",
       "dir": "ltr",
       "code": "public static Stack<int> CopyStack(Stack<int> s1)\n{\n    Stack<int> s2 = new Stack<int>();\n    while (!s1.IsEmpty())\n        s2.Push(s1.Pop());\n    Stack<int> s3 = new Stack<int>();\n    while (!s2.IsEmpty())\n    {\n        s1.Push(s2.Top()); // لاحظ أننا نستعمل هنا Top\n        s3.Push(s2.Pop());\n    }\n    return s3;\n}",
