       "code": "public static void Peach(Stack<int> st1)\n{\n    Stack<int> st2 = new Stack<int>();\n    int x, y;\n    while (!st1.IsEmpty())\n    {\n        x = st1.Pop();\n        if (!st1.IsEmpty())\n        {\n            y = st1.Pop();\n            st2.Push(y);\n        }\n        else\n            st2.Push(x);\n        st2.Push(x);\n    }\n    Console.WriteLine(\"st2=\" + st2);\n}",
